<?php namespace Database\Factories; use App\Models\Category; use App\Models\Product; use Illuminate\Database\Eloquent\Factories\Factory; use Illuminate\Support\Str; class ProductFactory extends Factory { protected $model = Product::class; public function definition(): array { return [ 'name' => ucfirst($this->faker->unique()->words(2, true)), 'barcode' => $this->faker->unique()->ean13(), 'sku' => strtoupper( $this->faker->unique()->bothify('SKU-#####') ), 'category_id' => Category::factory(), 'description' => $this->faker->sentence(), 'image' => null, 'is_active' => true, 'is_online' => true, ]; } }